=== Method: calc (AbstractMethod) ===
/* The purpose of this class is to determine the final brake torque request
   and related CSM Hold State Feedback information */


CsmHoldATarBrk = 0;
CsmHoldState = CSMHoldState_NotActive;
CsmHoldActive = false;
CsmHoldServiceStates = 0;

// Release Requests
if(in_CsmHoldDeactActive == true)
{
	CsmHoldServiceStates = OneBit.Write(CsmHoldServiceStates, CSMHoldServiceID_Deact);
	if(in_CsmHoldDeactATarBrk <= CsmHoldATarBrk)
	{
		CsmHoldATarBrk = in_CsmHoldDeactATarBrk;
		CsmHoldState = CSMHoldState_Deact;
	}
	
}

// Drive Off Requests
if(in_CsmHoldDriveOffActive == true)
{
	CsmHoldServiceStates = OneBit.Write(CsmHoldServiceStates, CSMHoldServiceID_DriveOff);
	if(in_CsmHoldDriveOffTrqSuffActive){
		CsmHoldServiceStates = OneBit.Write(CsmHoldServiceStates, CSMHoldServiceID_DriveOffComfortRelease);}
	if(in_CsmHoldDriveOffTrqBalActive){
		CsmHoldServiceStates = OneBit.Write(CsmHoldServiceStates, CSMHoldServiceID_DriveOffTrqBal);}
	if(in_CsmHoldDriveOffComfortReleaseActive){
		CsmHoldServiceStates = OneBit.Write(CsmHoldServiceStates, CSMHoldServiceID_DriveOffTrqSuff);}
	
	if(in_CsmHoldDriveOffATarBrk <= CsmHoldATarBrk)
	{
		CsmHoldATarBrk = in_CsmHoldDriveOffATarBrk;
		if(		in_CsmHoldDriveOffType == CSMDrvOffType_TorqueBalance
			&&	(	CsmDrvOffTrqBalMode == CSMDrvOffTrqBalMode_SensitiveWithBrkInc
				||	CsmDrvOffTrqBalMode == CSMDrvOffTrqBalMode_LessSensitiveWithBrkInc))
		{
			CsmHoldState = CSMHoldState_DriveOffTrqBal;
		}
		else
		{
			CsmHoldState = CSMHoldState_DriveOff;
		}
	}
}
	
// Hold Requests
if(in_CsmHoldBrkHoldActive == true)
{
	CsmHoldServiceStates = OneBit.Write(CsmHoldServiceStates, CSMHoldServiceID_BrkHold);
	if(in_CsmHoldBrkHoldForDriveOffActive){
		CsmHoldServiceStates = OneBit.Write(CsmHoldServiceStates, CSMHoldServiceID_HoldForDriveOff);}
	
	if(in_CsmHoldBrkHoldATarBrk <= CsmHoldATarBrk)
	{
		CsmHoldATarBrk = in_CsmHoldBrkHoldATarBrk;
		if(in_CsmHoldBrkHoldForDriveOffActive == true)
		{
			CsmHoldState = CSMHoldState_HoldForDriveOff;
		}else
		{
			CsmHoldState = CSMHoldState_BrkHold;
		}
	}
}

// Rollout Requests
if(in_CsmHoldRolloutActive == true)
{
	CsmHoldServiceStates = OneBit.Write(CsmHoldServiceStates, CSMHoldServiceID_Rollout);
	
	if(in_CsmHoldRolloutATarBrk < CsmHoldATarBrk)
	{
		CsmHoldATarBrk = in_CsmHoldRolloutATarBrk;
		CsmHoldState = CSMHoldState_BrkInc;
	}
}

// Brake Increase Request
if(in_CsmHoldBrkIncActive == true)
{
	CsmHoldServiceStates = OneBit.Write(CsmHoldServiceStates, CSMHoldServiceID_BrkInc);
	
	if(in_CsmHoldBrkIncATarBrk < CsmHoldATarBrk)
	{
		CsmHoldATarBrk = in_CsmHoldBrkIncATarBrk;
		CsmHoldState = CSMHoldState_BrkInc;
	}
}

// Roll Prevention 
if(in_CsmHoldRollPrevActive == true)
{
	CsmHoldServiceStates = OneBit.Write(CsmHoldServiceStates, CSMHoldServiceID_RollPrev);
	
	CsmHoldATarBrk = in_CsmHoldRollPrevATarBrk.min(CsmHoldATarBrk);
	CsmHoldState = CSMHoldState_RollPrev;
}


if((CsmHoldATarBrk < 0)||(CsmHoldDeactRampPlain > 1))
{
	CsmHoldState = CsmHoldState;
	CsmHoldActive = true;
}else
{
	// in very strict conditions even in case no brake is request CSMHoldState shall remain
	// used for torque balanced drive off to allow reactivation if required
	if(		in_CsmHoldDriveOffType == CSMDrvOffType_TorqueBalance
		&&	(	CsmDrvOffTrqBalMode == CSMDrvOffTrqBalMode_SensitiveWithBrkInc
			||	CsmDrvOffTrqBalMode == CSMDrvOffTrqBalMode_LessSensitiveWithBrkInc)
		&&	CsmHoldStateK1 == CSMHoldState_DriveOffTrqBal
		&&	CsmHoldStateK1 == CSMHoldState_DriveOffTrqBal)
	{
		CsmHoldState = CSMHoldState_DriveOffTrqBal;
		CsmHoldActive = true;
	}else
	{
		CsmHoldState = CSMHoldState_NotActive;
		CsmHoldActive = false;
	}
}


// HW limitation
if(CsmHoldATarBrk <= in_CsmHoldATarBrkLimit)
{
	CsmHoldATarBrk = in_CsmHoldATarBrkLimit;
	CsmHoldBrkLimitReached = true;
	CsmHoldState = CSMHoldState_BrkHold;
}else
{
	CsmHoldATarBrk = CsmHoldATarBrk;
	CsmHoldBrkLimitReached = false;
	CsmHoldState = CsmHoldState;
}

// Measure variables
p_CsmHoldATarBrk = (-CsmHoldATarBrk*C_UnladenMass)/C_p2F;

//Storage
CsmHoldStateK1 = CsmHoldState;


=== Method: CsmHoldActive (AbstractMethod) ===
return CsmHoldActive;


=== Method: CsmHoldATarBrk (AbstractMethod) ===
return CsmHoldATarBrk;


=== Method: CsmHoldServiceStates (AbstractMethod) ===
return CsmHoldServiceStates;


=== Method: CsmHoldState (AbstractMethod) ===
return CsmHoldState;
